  console.log(`\n##### ${file}`);
  console.log(`session wall: ${((last-first)/60000).toFixed(1)} min | tool calls: ${durs.length} | summed tool time: ${(total/60).toFixed(1)} min`);
  console.log('top 12 slowest tool calls (s):');
  for(const [d,l] of durs.slice(0,12)) console.log(`  ${d.toFixed(1)}  ${l}`);
  if(sleeps.length){console.log('sleeps:'); for(const s of sleeps.slice(0,10))console.log('  ',s[1],'|',s[0]);}
}
