// Dependency-free by design: a local pack's checks must load without the
// vendored mount, so this returns plain finding objects rather than importing
// engine/checks/helpers/findings.mjs.
//
// Converted from this pack's RULES.md ("The site is two independent front-ends
// — cross-page behaviour lives twice"). The Now page (js/app.js, a *classic*
// script) and the planner (plan/plan.js, an ES module) share no code, so a value
// both pages must agree on exists as two copies and drifts silently when a
// change lands in one. Canon's `shared-constants` guard can't hold this: it
// rejects an entry whose watched files are all import-capable (both are `.js`)
// on the grounds that they should share an import — true in general, not here,
// because index.html loads app.js without `type="module"`.
//
// Parsed, not grepped: the object literal is located by its declaration and read
// as key/value pairs, so a mention of `UK_BOUNDS` in a comment or a differently
// formatted (reordered keys, rewrapped lines, changed comment) copy can't raise
// a false alarm — only a real difference in the values does.

// The mirrored declarations. One entry per value that must be identical in both
// files; add a row when a new cross-page constant is copied.
const MIRRORS = [
  {
    name: 'UK_BOUNDS',
    files: ['js/app.js', 'plan/plan.js'],
    what: 'the UK-mainland bounding box that gates the location guard (Now) and the debug menu (Plan)',
  },
];

/** Text of the `{...}` object literal assigned to `const <name> =`, or null. */
function objectLiteralOf(text, name) {
  const decl = new RegExp(`(?:^|\\n)\\s*(?:const|let|var)\\s+${name}\\s*=\\s*\\{`);
  const m = decl.exec(text);
  if (!m) return null;
  const open = text.indexOf('{', m.index);
  let depth = 0;
  for (let i = open; i < text.length; i += 1) {
    const c = text[i];
    if (c === '{') depth += 1;
    else if (c === '}') {
      depth -= 1;
      if (depth === 0) {
        return { body: text.slice(open + 1, i), line: text.slice(0, open).split('\n').length };
      }
    }
  }
  return null; // unbalanced — the file doesn't parse anyway
}

function stripComments(s) {
  return s.replace(/\/\*[\s\S]*?\*\//g, ' ').replace(/\/\/[^\n]*/g, ' ');
}

/** Split on commas that are not inside a nested brace/bracket/paren or string. */
function topLevelParts(body) {
  const parts = [];
  let depth = 0;
  let quote = null;
  let start = 0;
  for (let i = 0; i < body.length; i += 1) {
    const c = body[i];
    if (quote) {
      if (c === '\\') i += 1;
      else if (c === quote) quote = null;
      continue;
    }
    if (c === '"' || c === "'" || c === '`') quote = c;
    else if (c === '{' || c === '[' || c === '(') depth += 1;
    else if (c === '}' || c === ']' || c === ')') depth -= 1;
    else if (c === ',' && depth === 0) {
      parts.push(body.slice(start, i));
      start = i + 1;
    }
  }
  parts.push(body.slice(start));
  return parts.map((p) => p.trim()).filter(Boolean);
}

/**
 * The literal's key -> value map. Values are normalised numerically when they
 * are numeric literals (so `49.8` and `49.80` are the same value, not drift) and
 * kept as collapsed source text otherwise — nothing here needs to *evaluate* the
 * file, only to tell two copies apart.
 */
function pairsOf(body) {
  const map = new Map();
  for (const part of topLevelParts(stripComments(body))) {
    const m = /^(?:(['"])([^'"]+)\1|([A-Za-z_$][\w$]*))\s*:\s*([\s\S]+)$/.exec(part);
    if (!m) {
      map.set(part.replace(/\s+/g, ' '), '<unparsed>'); // shorthand / spread — compared as text
      continue;
    }
    const key = m[2] ?? m[3];
    const raw = m[4].trim();
    const num = Number(raw);
    map.set(key, raw !== '' && Number.isFinite(num) ? String(num) : raw.replace(/\s+/g, ' '));
  }
  return map;
}

const rule = {
  id: 'edfringe-cross-page-mirrors',
  severity: 'blocking',
  description:
    'A constant the Now page and the planner both copy (they share no code) holds the same values in js/app.js and plan/plan.js',
  why:
    'the two front-ends share no modules and no globals, so a mirrored value changed on one page and not the other leaves the pages silently disagreeing — the copy that was not updated keeps the old behaviour and nothing else fails',
  doc: '.claudinite/local/packs/edfringe/RULES.md',

  run(ctx) {
    const out = [];

    const finding = (file, line, what, fix) => ({
      rule: rule.id,
      severity: rule.severity,
      file,
      line,
      what,
      why: rule.why,
      fix,
      doc: rule.doc,
    });

    for (const mirror of MIRRORS) {
      // Relevance-first: only a tree that has both pages can mirror anything.
      if (!mirror.files.every((f) => ctx.files.includes(f))) continue;

      const seen = [];
      for (const file of mirror.files) {
        const text = ctx.read(file);
        if (text === null) break;
        seen.push({ file, literal: objectLiteralOf(text, mirror.name) });
      }
      if (seen.length !== mirror.files.length) continue;

      const present = seen.filter((s) => s.literal);
      if (present.length === 0) continue; // dropped from both pages — nothing to mirror
      if (present.length !== seen.length) {
        const missing = seen.filter((s) => !s.literal).map((s) => s.file);
        const home = present[0];
        out.push(finding(home.file, home.literal.line,
          `${mirror.name} is declared in ${present.map((s) => s.file).join(', ')} but not in ${missing.join(', ')} — ${mirror.what}`,
          `restore the mirrored ${mirror.name} in ${missing.join(', ')}, or drop it from both pages and remove its row from MIRRORS in this check`));
        continue;
      }

      const [first, ...rest] = present.map((s) => ({ ...s, pairs: pairsOf(s.literal.body) }));
      for (const other of rest) {
        const keys = [...new Set([...first.pairs.keys(), ...other.pairs.keys()])].sort();
        const diffs = keys
          .filter((k) => first.pairs.get(k) !== other.pairs.get(k))
          .map((k) => `${k}: ${first.pairs.has(k) ? first.pairs.get(k) : '(absent)'} in ${first.file} vs ${other.pairs.has(k) ? other.pairs.get(k) : '(absent)'} in ${other.file}`);
        if (diffs.length === 0) continue;
        out.push(finding(other.file, other.literal.line,
          `${mirror.name} differs between the two front-ends — ${diffs.join('; ')}`,
          `the pages share no code, so ${mirror.name} is copied on purpose: apply the same change to every copy (${mirror.files.join(', ')})`));
      }
    }

    return out;
  },
};

export default rule;

// Red-first fixtures for this pack's check, plus a guard on the pack manifest.
//
// The check reads its files through the engine's `ctx`, so the fixtures here are
// tiny in-memory contexts ({ files, read }) — no temp dirs, no mount, and the
// same shape the real runner passes (engine/checks/helpers/repo-context.mjs).
// The last fixture runs the rule against this repo's ACTUAL js/app.js and
// plan/plan.js, which is what makes the check a live gate on the two pages
// rather than a self-fulfilling unit test.

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync, existsSync } from "node:fs";
import { fileURLToPath } from "node:url";
import path from "node:path";

import pack from "./pack.mjs";
import rule from "./cross-page-mirrors.mjs";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const REPO = path.resolve(__dirname, "../../../..");

const APP = "js/app.js";
const PLAN = "plan/plan.js";

/** A context over an in-memory {path: text} map, matching the engine's ctx. */
function ctxOf(tree) {
  const files = Object.keys(tree);
  return { files, read: (p) => (p in tree ? tree[p] : null) };
}

const APP_COPY = `
/* Very rough bounding box for the UK mainland (lat/lng).
 * MIRRORED in plan/plan.js — change both or the two pages disagree. */
const UK_BOUNDS = { minLat: 49.8, maxLat: 59.0, minLng: -8.2, maxLng: 1.9 };

function isInUK([lat, lng]) {
  return lat >= UK_BOUNDS.minLat && lat <= UK_BOUNDS.maxLat;
}
`;

// Deliberately not byte-identical to APP_COPY: a different comment, different
// wrapping, and a different key order. None of that is drift.
const PLAN_COPY = `
// Very rough UK-mainland bounding box (mirrors js/app.js).
const UK_BOUNDS = {
  maxLat: 59.0,
  minLat: 49.8,
  minLng: -8.2,
  maxLng: 1.9,
};
`;

test("identical mirrors produce no findings, whatever the formatting", () => {
  const out = rule.run(ctxOf({ [APP]: APP_COPY, [PLAN]: PLAN_COPY }));
  assert.deepEqual(out, [], `expected no findings, got ${JSON.stringify(out, null, 2)}`);
});

test("a value changed on one page only is reported", () => {
  // The exact regression this guards: the box is widened on the Now page and the
  // planner keeps gating its debug menu on the old one.
  const out = rule.run(ctxOf({
    [APP]: APP_COPY,
    [PLAN]: PLAN_COPY.replace("maxLat: 59.0", "maxLat: 61.0"),
  }));
  assert.equal(out.length, 1);
  assert.equal(out[0].rule, "edfringe-cross-page-mirrors");
  assert.equal(out[0].severity, "blocking");
  assert.equal(out[0].file, PLAN);
  assert.match(out[0].what, /UK_BOUNDS differs between the two front-ends/);
  assert.match(out[0].what, /maxLat: 59 in js\/app\.js vs 61 in plan\/plan\.js/);
  assert.ok(out[0].fix.includes(APP) && out[0].fix.includes(PLAN), "the fix must name both copies");
});

test("a key added to one copy only is reported", () => {
  const out = rule.run(ctxOf({
    [APP]: APP_COPY.replace("minLng: -8.2,", "minLng: -8.2, maxAlt: 2,"),
    [PLAN]: PLAN_COPY,
  }));
  assert.equal(out.length, 1);
  assert.match(out[0].what, /maxAlt: 2 in js\/app\.js vs \(absent\) in plan\/plan\.js/);
});

test("the constant disappearing from one page is reported, from both is not", () => {
  const dropped = rule.run(ctxOf({ [APP]: APP_COPY, [PLAN]: "// planner, no bounds here\n" }));
  assert.equal(dropped.length, 1);
  assert.match(dropped[0].what, /declared in js\/app\.js but not in plan\/plan\.js/);
  assert.equal(dropped[0].file, APP);

  // Removed on purpose from both pages: there is no mirror left to disagree.
  assert.deepEqual(rule.run(ctxOf({ [APP]: "// nothing\n", [PLAN]: "// nothing\n" })), []);
});

test("a mention outside the declaration is not mistaken for a copy", () => {
  // Grep would match this comment; parsing the declaration does not.
  const out = rule.run(ctxOf({
    [APP]: APP_COPY,
    [PLAN]: `${PLAN_COPY}\n// see UK_BOUNDS = { minLat: 0 } in js/app.js for the real box\n`,
  }));
  assert.deepEqual(out, []);
});

test("only one of the two pages in the tree ⇒ no findings (relevance-first)", () => {
  assert.deepEqual(rule.run(ctxOf({ [APP]: APP_COPY })), []);
  assert.deepEqual(rule.run(ctxOf({ "README.md": "# hi" })), []);
});

test("this repo's two front-ends agree", () => {
  // The live gate: the real files off disk.
  const files = [APP, PLAN];
  assert.ok(files.every((f) => existsSync(path.join(REPO, f))), "expected both front-ends to be present");
  const out = rule.run({
    files,
    read: (p) => (files.includes(p) ? readFileSync(path.join(REPO, p), "utf8") : null),
  });
  assert.deepEqual(out, [], `the two pages disagree:\n${out.map((f) => `${f.file}: ${f.what}`).join("\n")}`);
});

test("the pack manifest declares the check and stays hand-declared", () => {
  assert.equal(pack.id, "edfringe");
  assert.equal(pack.detect, null, "a local pack is never fingerprinted");
  assert.equal(pack.marker, null);
  assert.equal(pack.prose, "RULES.md");
  assert.ok(pack.rules.includes(rule), "the check must be listed on the manifest or it never runs");
  assert.ok(existsSync(path.join(__dirname, "RULES.md")));
});

