// One argv-driven browser driver, re-pointed per shot (per edfringe RULES.md).
//   node drive.mjs <url> <screenshot-path> [waitMs]
import { chromium } from "/opt/node22/lib/node_modules/playwright/index.mjs";

const [url, shot, waitMs = "2500"] = process.argv.slice(2);

// Known-benign noise this repo always emits when served locally (RULES.md).
const BENIGN = [/favicon\.ico/i, /ERR_CONNECTION_RESET/i, /net::ERR_FAILED.*favicon/i];
const noisy = (t) => BENIGN.some((re) => re.test(t));

const browser = await chromium.launch();
const page = await browser.newPage();

const errors = [];
page.on("console", (m) => {
  if (m.type() === "error" && !noisy(m.text())) errors.push(`console: ${m.text()}`);
});
page.on("pageerror", (e) => {
  if (!noisy(String(e))) errors.push(`pageerror: ${e.message}`);
});
page.on("requestfailed", (r) => {
  const t = `${r.url()} ${r.failure()?.errorText ?? ""}`;
  if (!noisy(t)) errors.push(`requestfailed: ${t}`);
});

await page.goto(url, { waitUntil: "networkidle" });
await page.waitForTimeout(Number(waitMs));
await page.screenshot({ path: shot, fullPage: false });

// A few DOM facts that prove the module actually executed, not just loaded.
const probe = await page.evaluate(() => ({
  title: document.title,
  cards: document.querySelectorAll(".show-card, .show, [class*='show-card']").length,
  leafletTiles: document.querySelectorAll(".leaflet-tile").length,
  listChildren: document.querySelector("#showList, #list, .show-list")?.children.length ?? -1,
  bodyText: document.body.innerText.slice(0, 160).replace(/\s+/g, " "),
}));

console.log(JSON.stringify({ url, probe, errors }, null, 2));
await browser.close();
process.exit(errors.length ? 1 : 0);

